//! Botanical plates shown as species covers: historical illustrations from Wikimedia Commons,
//! chosen one per species. Generated from the selection made with the review page (see
//! README, "Species illustrations"); the full credits are in `public/assets/species/CREDITS.csv`.

use crate::i18n::{Lang, pick};

#[derive(Debug, PartialEq)]
pub struct Plate {
    /// Scientific name exactly as in the catalog.
    pub species: &'static str,
    /// File in `public/assets/species/`.
    pub image: &'static str,
    /// File name on Wikimedia Commons.
    pub title: &'static str,
    /// Author(s) as given on Commons; empty when unknown.
    pub artist: &'static str,
    /// Year of the plate or of the source, when Commons gives one.
    pub year: &'static str,
    pub license: &'static str,
    /// Commons file page (author, source and license).
    pub page: &'static str,
}

impl Plate {
    pub fn src(&self) -> String {
        format!("/assets/species/{}", self.image)
    }

    /// "Author, year" (or "Unknown author").
    pub fn byline(&self, l: Lang) -> String {
        let who = if self.artist.is_empty() { pick(l, "Autor desconocido", "Unknown author") } else { self.artist };
        if self.year.is_empty() { who.to_string() } else { format!("{who}, {}", self.year) }
    }
}

